@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:wght@500;700;800&family=Manrope:wght@400;500;700&display=swap');

:root {
  --bg: #f5f2ed;
  --bg-soft: #ece6de;
  --text: #1a1a1a;
  --muted: #5f574f;
  --line: #d8cfc4;
  --accent-1: #c8865f;
  --accent-2: #9cab8c;
  --accent-3: #d8c29c;
  --accent-4: #ad7a6d;
}

* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
body {
  font-family: 'Manrope', sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
}

a { color: inherit; text-decoration: none; }

.page {
  min-height: 100vh;
  padding: 2rem clamp(1.25rem, 3vw, 3rem) 4rem;
}

.site-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  position: sticky;
  top: 0;
  backdrop-filter: blur(6px);
  background: color-mix(in srgb, var(--bg) 88%, transparent);
  border-bottom: 1px solid color-mix(in srgb, var(--line) 75%, transparent);
  z-index: 40;
  padding: 1rem clamp(1.25rem, 3vw, 3rem);
  margin: -2rem clamp(-1.25rem, -3vw, -3rem) 2rem;
}

.brand {
  font-family: 'Playfair Display', serif;
  font-size: 1.35rem;
  letter-spacing: 0.02em;
}

.nav-links { display: flex; gap: 1.4rem; }
.nav-links a {
  font-size: 0.86rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--muted);
}
.nav-links a.active { color: var(--text); }

.menu-toggle {
  display: none;
  width: 2.3rem;
  height: 2.3rem;
  border: 1px solid var(--line);
  background: transparent;
  color: var(--text);
  border-radius: 999px;
  align-items: center;
  justify-content: center;
  font-size: 1.2rem;
}

.mobile-menu {
  position: fixed;
  inset: 0;
  background: color-mix(in srgb, var(--bg) 95%, #000 5%);
  display: grid;
  place-items: center;
  transform: translateY(-100%);
  transition: transform .35s ease;
  z-index: 35;
}
.mobile-menu.open { transform: translateY(0); }
.mobile-menu nav {
  display: flex;
  flex-direction: column;
  gap: 1.1rem;
  text-align: center;
}
.mobile-menu a {
  font-family: 'Playfair Display', serif;
  font-size: clamp(1.8rem, 7vw, 3rem);
}

.hero {
  margin-top: 5vh;
  display: grid;
  grid-template-columns: 1.2fr .8fr;
  gap: clamp(1.2rem, 4vw, 4rem);
  align-items: start;
}

.eyebrow {
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-size: 0.75rem;
  color: var(--muted);
  margin-bottom: 1rem;
}

h1, h2, h3 {
  font-family: 'Playfair Display', serif;
  line-height: 1.05;
  margin: 0;
  font-weight: 700;
}

.hero h1 {
  font-size: clamp(2.6rem, 7.5vw, 6.5rem);
  max-width: 16ch;
}

.lead {
  margin-top: 1.4rem;
  max-width: 42ch;
  color: color-mix(in srgb, var(--text) 90%, var(--muted));
}

.placeholder-grid {
  margin-top: clamp(3rem, 9vw, 7rem);
  display: grid;
  grid-template-columns: repeat(12, 1fr);
  gap: .8rem;
}
.block {
  border-radius: 2px;
  min-height: 130px;
}
.b1 { grid-column: span 7; background: var(--accent-1); min-height: 190px; }
.b2 { grid-column: span 5; background: var(--accent-2); min-height: 220px; }
.b3 { grid-column: span 4; background: var(--accent-3); min-height: 160px; }
.b4 { grid-column: span 8; background: var(--accent-4); min-height: 170px; }

.section {
  margin-top: clamp(4rem, 9vw, 8rem);
}

.section-title {
  font-size: clamp(1.8rem, 4.6vw, 3.6rem);
  margin-bottom: 1.4rem;
}

.marquee-wrap {
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  padding: 1rem 0;
  overflow: hidden;
  display: grid;
  gap: 0.9rem;
}
.marquee-row {
  overflow: hidden;
  white-space: nowrap;
  mask-image: linear-gradient(90deg, transparent, #000 8%, #000 92%, transparent);
}
.marquee-track {
  display: inline-flex;
  gap: 2rem;
  min-width: max-content;
  will-change: transform;
  animation: marquee-left 26s linear infinite;
}
.marquee-row.reverse .marquee-track { animation-name: marquee-right; }
.marquee-item {
  font-family: 'Playfair Display', serif;
  font-size: clamp(1.2rem, 2.2vw, 1.9rem);
  letter-spacing: .01em;
}

@keyframes marquee-left {
  from { transform: translateX(0); }
  to { transform: translateX(-50%); }
}
@keyframes marquee-right {
  from { transform: translateX(-50%); }
  to { transform: translateX(0); }
}

.services-list {
  display: grid;
  gap: 2.2rem;
  max-width: 70rem;
}
.service-item {
  border-top: 1px solid var(--line);
  padding-top: 1.2rem;
  display: grid;
  grid-template-columns: 1fr 2fr;
  gap: 1.2rem;
}
.service-item h3 { font-size: clamp(1.6rem, 4vw, 2.8rem); }

.letter {
  max-width: 42rem;
  margin: 0 auto;
}
.letter h1 {
  font-size: clamp(2.2rem, 6vw, 4.8rem);
  margin-bottom: 2rem;
}
.letter p {
  font-size: clamp(1.02rem, 2vw, 1.22rem);
  margin: 1.1rem 0;
  color: #2b2927;
}
.signature {
  margin-top: 2.3rem;
  font-family: 'Playfair Display', serif;
  font-size: 1.3rem;
}

.clients-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1.2rem 1.8rem;
}
.client-card {
  border-top: 1px solid var(--line);
  padding-top: .8rem;
}
.client-card h3 { font-size: 1.55rem; margin-bottom: .4rem; }
.client-card p { margin: 0; color: var(--muted); font-size: .94rem; }

.contact-hero {
  min-height: 62vh;
  display: grid;
  align-content: center;
}
.contact-hero h1 {
  font-size: clamp(4rem, 19vw, 17rem);
  line-height: .9;
}
.contact-links {
  display: flex;
  gap: 1.6rem;
  justify-content: center;
  font-family: 'Playfair Display', serif;
  font-size: clamp(1.3rem, 3vw, 2rem);
}

@media (max-width: 900px) {
  .hero { grid-template-columns: 1fr; }
  .service-item { grid-template-columns: 1fr; }
  .clients-grid { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 760px) {
  .nav-links { display: none; }
  .menu-toggle { display: inline-flex; }
  .clients-grid { grid-template-columns: 1fr; }
  .page { padding-top: 1.2rem; }
}
EOF

